bool number(const var& v,double low,double high,bool integer=false){if(!(v.isInt()||v.isInt64()||v.isDouble()))return false;double n=(double)v;return std::isfinite(n)&&n>=low&&n<=high&&(!integer||n==std::floor(n));}
bool text(const var& v,int limit){if(!v.isString()||v.toString().trim().isEmpty()||v.toString().length()>limit)return false;for(auto c:v.toString())if(c<32||c==127)return false;return true;}
bool keys(const var& v,std::initializer_list<const char*> names){if(!v.isObject())return false;for(const auto& field:v.getDynamicObject()->getProperties()){bool found=false;for(auto name:names)found|=field.name.toString()==name;if(!found)return false;}return true;}
Result fail(const String& message){return Result::fail(message);}
bool index(const var& v,size_t count){return count>0&&number(v,0,(double)count-1,true);}
bool instrument(const String& name,Instrument& output){const char* names[]={"kick","snare","hat","clap","open_hat","bass","pad","lead","sample","analog","fm","wavetable"};for(int i=0;i<instrumentCount;++i)if(name==names[i]&&i!=8){output=(Instrument)i;return true;}return false;}
Result trackSettings(const var& op,Track& t){
    if(op.hasProperty("name")){if(!text(op["name"],80))return fail("Track name must contain 1-80 printable characters.");t.name=op["name"].toString();}
    if(op.hasProperty("instrument")){if(t.isBus||!op["instrument"].isString()||!instrument(op["instrument"].toString(),t.instrument))return fail("Choose a built-in instrument; buses keep their identity.");t.samplePath.clear();}
    if(op.hasProperty("preset")){if(!op["preset"].isString())return fail("Preset must be a factory sound name.");auto it=std::find_if(factorySynthPresets().begin(),factorySynthPresets().end(),[&](const SynthPreset& p){return p.name==op["preset"].toString();});if(it==factorySynthPresets().end()||t.isBus)return fail("Factory sound is unavailable for this track.");if(op.hasProperty("instrument")&&t.instrument!=it->instrument)return fail("Preset and instrument do not match.");t.instrument=it->instrument;t.synth=it->patch;t.attack=it->attack;t.release=it->release;t.soundName=it->name;t.samplePath.clear();}
    if(op.hasProperty("synth")){if(t.isBus||!isSynth(t.instrument)||!op["synth"].isObject())return fail("Synth overrides require an Analog, FM or Wavetable track.");auto patch=synthPatchToJson(t.synth);for(const auto& field:op["synth"].getDynamicObject()->getProperties()){if(!patch.hasProperty(field.name))return fail("Unknown synth parameter: "+field.name.toString());patch.getDynamicObject()->setProperty(field.name,field.value);}auto valid=synthPatchFromJson(patch,t.synth,true);if(valid.failed())return valid;t.soundName="Custom MCP sound";}
    if(op.hasProperty("params")){auto p=op["params"];if(!keys(p,{"volume","pan","cutoff","drive","send","attack","release"}))return fail("Unknown track parameter.");
        struct Setting{const char* name;float* value;double low,high;};for(auto s:{Setting{"volume",&t.volume,0,1.5},{"pan",&t.pan,-1,1},{"cutoff",&t.cutoff,60,20000},{"drive",&t.drive,0,1},{"send",&t.send,0,.8},{"attack",&t.attack,.001,2},{"release",&t.release,.02,3}})if(p.hasProperty(s.name)){if(!number(p[s.name],s.low,s.high))return fail("Invalid track parameter: "+String(s.name));*s.value=(float)(double)p[s.name];}}
    if(op.hasProperty("effects")){auto effects=op["effects"];if(!keys(effects,{"eq","reverb","chorus","stereo"}))return fail("Unknown control effect.");auto& fx=t.mixer;
        if(effects.hasProperty("eq")){auto p=effects["eq"];if(!keys(p,{"low","mid","high","enabled"}))return fail("Invalid EQ settings.");fx.eq=true;for(auto pair:{std::pair{"low",&fx.low},std::pair{"mid",&fx.mid},std::pair{"high",&fx.high}})if(p.hasProperty(pair.first)){if(!number(p[pair.first],-18,18))return fail("EQ gain must be between -18 and +18 dB.");*pair.second=(float)(double)p[pair.first];}if(p.hasProperty("enabled")){if(!p["enabled"].isBool())return fail("EQ enabled must be boolean.");fx.eq=(bool)p["enabled"];}}
        if(effects.hasProperty("reverb")){auto p=effects["reverb"];if(!keys(p,{"mix","room","damping","enabled"}))return fail("Invalid reverb settings.");fx.reverb=true;for(auto pair:{std::pair{"mix",&fx.reverbMix},std::pair{"room",&fx.room},std::pair{"damping",&fx.damping}})if(p.hasProperty(pair.first)){if(!number(p[pair.first],0,1))return fail("Reverb parameters must be 0-1.");*pair.second=(float)(double)p[pair.first];}if(p.hasProperty("enabled")){if(!p["enabled"].isBool())return fail("Reverb enabled must be boolean.");fx.reverb=(bool)p["enabled"];}}
        for(auto key:{"chorus","stereo"})if(effects.hasProperty(key)){auto p=effects[key];if(!p.isObject())return fail("Invalid effect object.");auto settings=String(key)=="chorus"?chorusToJson(fx.chorus):stereoToJson(fx.stereo);settings.getDynamicObject()->setProperty("enabled",true);for(const auto& field:p.getDynamicObject()->getProperties()){if(!settings.hasProperty(field.name))return fail("Unknown effect parameter.");settings.getDynamicObject()->setProperty(field.name,field.value);}auto valid=String(key)=="chorus"?chorusFromJson(settings,fx.chorus):stereoFromJson(settings,fx.stereo);if(valid.failed())return valid;}}
    if(op.hasProperty("output")){if(!number(op["output"],-1,maxTracks-1,true))return fail("Invalid output bus index.");t.mixer.output=(int)op["output"];}
    return Result::ok();
}
