Result applyControlEdits(const Project& source,const var& operations,Project& output){
    auto* ops=operations.getArray();if(!ops||ops->isEmpty()||ops->size()>128)return fail("Use 1-128 operations per atomic edit.");Project next=source;
    for(const auto& op:*ops){if(!op.isObject()||!op["op"].isString())return fail("Every operation needs an op name.");auto kind=op["op"].toString();
        if(kind=="set_song"){if(!keys(op,{"op","title","bpm","swing","master","delayFeedback","songMode","loop","metronome","notes"}))return fail("Unknown song setting.");if(op.hasProperty("title")){if(!text(op["title"],200))return fail("Invalid song title.");next.title=op["title"].toString();}if(op.hasProperty("notes")){if(!op["notes"].isString()||op["notes"].toString().length()>16000)return fail("Song notes must be text up to 16000 characters.");next.notes=op["notes"].toString();}
            if(op.hasProperty("bpm")){if(!number(op["bpm"],30,300))return fail("Tempo must be 30-300 BPM.");next.bpm=(double)op["bpm"];}for(auto p:{std::pair{"swing",&next.swing},std::pair{"master",&next.master},std::pair{"delayFeedback",&next.delayFeedback}})if(op.hasProperty(p.first)){double high=String(p.first)=="swing"?.6:String(p.first)=="delayFeedback"?.8:1.;if(!number(op[p.first],0,high))return fail("Invalid song level or swing.");*p.second=(float)(double)op[p.first];}for(auto p:{std::pair{"songMode",&next.songMode},std::pair{"loop",&next.loop},std::pair{"metronome",&next.metronome}})if(op.hasProperty(p.first)){if(!op[p.first].isBool())return fail("Song switches require boolean values.");*p.second=(bool)op[p.first];}}
        else if(kind=="add_track"||kind=="set_track"){
            if(!keys(op,{"op","track","name","instrument","preset","synth","params","effects","output","bus"}))return fail("Unknown track property.");bool adding=kind=="add_track";if(adding&&next.tracks.size()>=maxTracks)return fail("The project has reached 16 tracks.");if(!adding&&!index(op["track"],next.tracks.size()))return fail("Track index is unavailable.");Track t=adding?Track{}:next.tracks[(size_t)(int)op["track"]];
            if(adding){if(!text(op["name"],80))return fail("New tracks need a name.");if(op.hasProperty("bus")&&!op["bus"].isBool())return fail("Bus must be boolean.");t.isBus=(bool)op["bus"];if(!t.isBus&&!op.hasProperty("instrument")&&!op.hasProperty("preset"))return fail("New source tracks need an instrument or preset.");}else if(op.hasProperty("bus"))return fail("Existing tracks cannot change source/bus identity.");
            auto valid=trackSettings(op,t);if(valid.failed())return valid;if(adding){next.tracks.push_back(t);for(auto& pat:next.patterns)pat.lanes.resize(next.tracks.size());}else next.tracks[(size_t)(int)op["track"]]=t;}
        else if(kind=="add_pattern"||kind=="set_pattern"){
            if(!keys(op,{"op","pattern","name","length","colour"}))return fail("Unknown pattern property.");bool adding=kind=="add_pattern";if(adding&&next.patterns.size()>=maxPatterns)return fail("The project has reached 32 patterns.");if(!adding&&!index(op["pattern"],next.patterns.size()))return fail("Pattern index is unavailable.");Pattern p=adding?Pattern{}:next.patterns[(size_t)(int)op["pattern"]];if(op.hasProperty("name")){if(!text(op["name"],100))return fail("Invalid pattern name.");p.name=op["name"].toString();}else if(adding)return fail("New patterns need a name.");if(op.hasProperty("length")){if(!number(op["length"],1,64))return fail("Pattern length must be 1-64 beats.");p.length=(double)op["length"];for(const auto& lane:p.lanes)for(const auto& n:lane)if(n.beat>=p.length)return fail("The shorter pattern would exclude notes; edit its notes first.");}if(op.hasProperty("colour")){if(!number(op["colour"],0,patternColourCount-1,true))return fail("Pattern colour must be an integer from 0 to 12.");p.colour=(int)op["colour"];}p.lanes.resize(next.tracks.size());if(adding)next.patterns.push_back(std::move(p));else next.patterns[(size_t)(int)op["pattern"]]=std::move(p);}
        else if(kind=="extract_notes"){
            if(!keys(op,{"op","pattern","track","indices","move","alignStart"})||!index(op["pattern"],next.patterns.size())||!index(op["track"],next.tracks.size())||!op["indices"].isArray()||op["indices"].getArray()->isEmpty()||op["indices"].getArray()->size()>maxNotesPerLane)return fail("Extraction needs a pattern, track and 1-512 unique note indices.");
            for(auto key:{"move","alignStart"})if(op.hasProperty(key)&&!op[key].isBool())return fail("Extraction switches must be boolean.");
            std::set<int> selection;for(const auto& i:*op["indices"].getArray())if(!number(i,0,maxNotesPerLane-1,true)||!selection.insert((int)i).second)return fail("Extraction note indices must be unique integers from 0 to 511.");
            Project extracted;auto valid=extractPatternNotes(next,(int)op["pattern"],(int)op["track"],selection,(bool)op["move"],(bool)op["alignStart"],extracted);if(valid.failed())return valid;next=std::move(extracted);
        }
        else if(kind=="merge_patterns"){
            if(!keys(op,{"op","first","second","mode","policy"})||!index(op["first"],next.patterns.size())||!index(op["second"],next.patterns.size()))return fail("Choose two valid patterns to merge.");
            String mode="layered",policy="keep_all";if(op.hasProperty("mode")){if(!op["mode"].isString())return fail("Merge mode must be layered or sequential.");mode=op["mode"].toString();}if(op.hasProperty("policy")){if(!op["policy"].isString())return fail("Merge conflict policy must be a string.");policy=op["policy"].toString();}
            int p=-1;const char* policies[]={"keep_all","skip_exact","prefer_first","prefer_second"};for(int i=0;i<4;++i)if(policy==policies[i])p=i;
            if(p<0||(mode!="layered"&&mode!="sequential")||(mode=="sequential"&&p!=0))return fail("Choose a valid merge mode/policy; sequential merges require keep_all.");
            Project merged;auto valid=mode=="sequential"?mergePatternSequence(next,(int)op["first"],(int)op["second"],merged):mergePatternLayers(next,(int)op["first"],(int)op["second"],merged,nullptr,(PatternMergePolicy)p);if(valid.failed())return valid;next=std::move(merged);
        }
        else if(kind=="set_notes"){
            if(!keys(op,{"op","pattern","track","notes"})||!index(op["pattern"],next.patterns.size())||!index(op["track"],next.tracks.size())||!op["notes"].isArray()||op["notes"].getArray()->size()>maxNotesPerLane)return fail("Invalid notes target or more than 512 notes.");int track=(int)op["track"];if(next.tracks[(size_t)track].isBus)return fail("Mixer buses do not hold notes.");auto& p=next.patterns[(size_t)(int)op["pattern"]];std::vector<Note> notes;
            for(const auto& n:*op["notes"].getArray()){if(!keys(n,{"beat","length","pitch","velocity","probability","ratchets"})||!number(n["beat"],0,p.length)||((double)n["beat"]>=p.length)||!number(n["length"],.01,64)||!number(n["pitch"],0,127,true)||!number(n["velocity"],0,1))return fail("Invalid note timing, pitch or velocity.");Note note{(double)n["beat"],(double)n["length"],(int)n["pitch"],(float)(double)n["velocity"]};if(n.hasProperty("probability")){if(!number(n["probability"],0,1))return fail("Invalid note probability.");note.probability=(float)(double)n["probability"];}if(n.hasProperty("ratchets")){if(!number(n["ratchets"],1,8,true))return fail("Invalid note ratchet count.");note.ratchets=(int)n["ratchets"];}notes.push_back(note);}p.lanes[(size_t)track]=std::move(notes);}
        else if(kind=="set_arrangement"){
            if(!keys(op,{"op","clips"})||!op["clips"].isArray()||op["clips"].getArray()->size()>maxClips)return fail("Arrangement must contain at most 512 clips.");std::vector<Clip> clips;for(const auto& c:*op["clips"].getArray()){if(!keys(c,{"track","pattern","beat","length"})||!index(c["track"],next.tracks.size())||next.tracks[(size_t)(int)c["track"]].isBus||!index(c["pattern"],next.patterns.size())||!number(c["beat"],0,4096)||!number(c["length"],.0625,600)||(double)c["beat"]+(double)c["length"]>4096)return fail("Invalid pattern clip, position or duration.");clips.push_back({(int)c["track"],(int)c["pattern"],(double)c["beat"],(double)c["length"]});}next.clips=std::move(clips);}
        else if(kind=="set_markers"){
            if(!keys(op,{"op","markers"})||!op["markers"].isArray()||op["markers"].getArray()->size()>maxSongMarkers)return fail("Invalid section list.");std::vector<SongMarker> markers;for(const auto& m:*op["markers"].getArray()){if(!keys(m,{"id","name","beat","endBeat","colour"})||!text(m["id"],80)||!text(m["name"],80)||!number(m["beat"],0,4096)||!number(m["colour"],0,7,true)||(m.hasProperty("endBeat")&&!number(m["endBeat"],-1,4096)))return fail("Invalid song marker.");markers.push_back({m["id"].toString(),m["name"].toString(),(double)m["beat"],m.hasProperty("endBeat")?(double)m["endBeat"]:-1,(int)m["colour"]});}next.markers=std::move(markers);next.loopSection.clear();}
        else if(kind=="section_clips"){
            if(!keys(op,{"op","section","destination","move","allowOverlap"})||!text(op["section"],80)||!number(op["destination"],0,4096))return fail("Section clips need a section id and destination in beats 0-4096.");
            for(auto key:{"move","allowOverlap"})if(op.hasProperty(key)&&!op[key].isBool())return fail("Section clip switches must be boolean.");
            Project arranged;auto valid=transformSectionClips(next,op["section"].toString(),(double)op["destination"],(bool)op["move"],(bool)op["allowOverlap"],arranged);if(valid.failed())return valid;next=std::move(arranged);
        }
        else if(kind=="add_automation"){
            if(!keys(op,{"op","track","target","targetTrack","beat","length","points"})||next.clips.size()>=maxClips||!index(op["track"],next.tracks.size())||!number(op["target"],0,5,true)||!number(op["targetTrack"],-1,(double)next.tracks.size()-1,true)||!number(op["beat"],0,4096)||!number(op["length"],.0625,600)||(double)op["beat"]+(double)op["length"]>4096||!op["points"].isArray()||op["points"].getArray()->size()<2||op["points"].getArray()->size()>maxAutomationPoints)return fail("Invalid automation clip.");Clip c;c.track=(int)op["track"];c.automationTarget=(int)op["target"];c.automationTrack=(int)op["targetTrack"];c.beat=(double)op["beat"];c.length=(double)op["length"];if(c.automationTarget!=5&&c.automationTrack<0)return fail("Channel automation needs a target track.");double previous=-1;for(const auto& p:*op["points"].getArray()){if(!keys(p,{"beat","value","hold"})||!number(p["beat"],0,c.length)||(double)p["beat"]<=previous||!number(p["value"],0,1)||(p.hasProperty("hold")&&!p["hold"].isBool()))return fail("Automation points need increasing beats and normalized values.");previous=(double)p["beat"];c.points.push_back({previous,(float)(double)p["value"],(bool)p["hold"]});}if(c.points.front().beat!=0||c.points.back().beat!=c.length)return fail("Automation must include both endpoints.");next.clips.push_back(std::move(c));}
        else return fail("Unknown edit operation: "+kind);
    }
    auto valid=validateRouting(next);if(valid.failed())return valid;valid=validateSongMarkers(next);if(valid.failed())return valid;Project checked;valid=projectFromJson(projectToJson(next),checked);if(valid.failed())return valid;
    output=std::move(next);return Result::ok();
}
